-- koloni-290: Efe ana × Kafkas baba (2'li melez) + Efe arısı arşiv kaydı + «Ege ekotipi = Muğla arısı» notu düzeltmesi. Kilitli Genetik tablosu aynı (efe+kafkas → anadolu+kafkas 55 takma, uzman tahmini).
insert into public.kural_kaynaklari (id, grup, sira, ad, degerler, seviye, aciklama, kaynak, durum) values
 ('melez_efe_ana_kafkas_baba','oğul skoru',20,'Melez: Efe ana × Kafkas baba','Genetik: 55 (Anadolu × Kafkas basamağı) · Oğul ölçeği: Veri yok','—','Bu melezle oğul/verim denemesi yok (Veri yok). Antalya → Tekman → Muğla tahmini 30–50 kg (olası 35–45). Ege × Kafkas (Aydın): 21,81 kg, saf Kafkas 23,00 kg. Genetik puanı ve verim uzman tahmini.','Resmî Gazete 16.05.2019 — https://www.resmigazete.gov.tr/eskiler/2019/05/20190516-14.htm · Gençer & Karacaoğlu 2003 — https://dergipark.org.tr/en/download/article-file/204927','uzman tahmini')
on conflict (id) do update set degerler=excluded.degerler, aciklama=excluded.aciklama, kaynak=excluded.kaynak, durum=excluded.durum, updated_at=now();
insert into public.yapilacaklar (baslik, aciklama)
select v.b, v.a from (values
 ('Efe ana × Kafkas baba Genetik puanı uzman tahmini (55)','Kilitli tabloya anahtar eklenmedi; efe+kafkas, Anadolu × Kafkas basamağını (55) kullanıyor. Bu melezle oğul eğilimi ve verim denemesi aranmalı. Verim tahmini (30–50 kg) uzman tahmini. Yönetici › Oğul skoru › Anadolu × Kafkas değeri değiştirilirse bu melez de onu izler; kaynak satırı Kural kaynakları bölümünde düzenlenebilir.')
) as v(b,a) where not exists (select 1 from public.yapilacaklar y where y.baslik = v.b);
update public.bilgi_kayitlari set icerik=replace(icerik,'Not: Ege ekotipi = Muğla arısı (ADÜ kaynakları).','Not: Efe (Batı Ege) arısı İzmir''in tescilli hattıdır, Muğla arısı değildir (Resmî Gazete 16.05.2019; Muğla arısı tescil edilmedi). ADÜ çalışmalarındaki «Ege ekotipi» de Muğla arısıyla eş tutulmamalı.'), updated_at=now() where icerik like '%Ege ekotipi = Muğla arısı%';
insert into public.bilgi_kayitlari (id,klasor_id,baslik,icerik,durum,kaynaklar,sira) values ('irk-efe','irk','Efe arısı (tescilli Ege hattı, İzmir)','Efe arısı (eski adı Batı Ege arısı): Apis mellifera anatoliaca, Ege Tarımsal Araştırma Enstitüsü (İzmir) 2008–2018 ıslahı; tescil kararı 26.12.2018, Resmî Gazete 16.05.2019; Milli Tescil Listesi 14.10.2020. İzmir çevresinde taşınmamış kolonilerden seçildi. Muğla arısı DEĞİLDİR; aynı kararda Muğla arısının tescili uygun görülmedi.
• TAGEM: bölge arılarına göre koloni indeksi %20, bal verimi %25 yüksek; hırçınlık ve oğul eğilimi azaltılmış; çamdan bal toplama eğilimi yüksek; kışlama iyi.
• AA (enstitü açıklaması): bal verimi bölge arılarına göre %25–35 yüksek.
• Eşek Adası (beestudies id=67): koloni başı 2–12 kg.
• Hijyenik davranış: DergiPark 5233792.
• Ege × Kafkas melezi (Gençer & Karacaoğlu 2003, Aydın): Ege × Kafkas 21,8 kg, saf Kafkas 23,0 kg (fark önemsiz).
Uzman tahmini: Efe ana × Kafkas baba Antalya → Tekman → Muğla güzergâhında 30–50 kg, olası 35–45 kg. Şampiyon yine Muğla ana × Kafkas baba (Akyol 1998: 65,0 kg; Yeninar 2009: 55,3 kg).
Efe ana × Kafkas baba ile doğrudan deneme: Veri yok.','karışık','[{"ad":"AA, Bal arısı «efe» tescillendi (28.02.2019)","url":"https://www.aa.com.tr/tr/turkiye/bal-arisi-efe-tescillendi-/1405263"},{"ad":"AA, «Efe arısı» ve «Gökçeada arısı» tescil edildi (14.10.2020)","url":"https://www.aa.com.tr/tr/turkiye/efe-arisi-ve-gokceada-arisi-tescil-edildi/2006308"},{"ad":"Resmî Gazete 16.05.2019 sayı 30776 (tescil kararı)","url":"https://www.resmigazete.gov.tr/eskiler/2019/05/20190516-14.htm"},{"ad":"Resmî Gazete 14.10.2020, Yerli Hayvan Irk ve Hatlarının Tescili Tebliği","url":"https://www.resmigazete.gov.tr/eskiler/2020/10/20201014-3-1.pdf"},{"ad":"TAGEM / Ege Tarımsal Araştırma Enst.: Efe arısı ekotipi tescil edildi (%20 koloni indeksi, %25 bal)","url":"https://arastirma.tarimorman.gov.tr/etae/Sayfalar/GormeEngellilerDetay.aspx?Liste=Haber&OgeId=240"},{"ad":"Arıcılık Araştırma Dergisi (beestudies id=67) — Eşek Adası","url":"https://www.beestudies.org/pdf.php?id=67"},{"ad":"DergiPark makale 5233792 (hijyenik davranış)","url":"https://dergipark.org.tr/tr/download/article-file/5233792"},{"ad":"Gençer & Karacaoğlu (2003), YYÜ Tarım Bil. Derg. 13(1)","url":"https://dergipark.org.tr/en/download/article-file/204927"}]'::jsonb,60) on conflict (id) do update set icerik=excluded.icerik,kaynaklar=excluded.kaynaklar,durum=excluded.durum,baslik=excluded.baslik,updated_at=now();
